    pub static T: [u16; NB] = [6, 8, 14, 4, 4, 4, 6, 10, 8];
    pub static BLOCK_PC: [u32; NB] = [0x728, 0x740, 0x760, 0x798, 0x7a8, 0x7b8, 0x7c8, 0x7e0, 0x808];
    /// Edge e: target pc, target block (or EXIT).
    pub static EDGE_TO: [u32; NE] = [0x300, 0x740, 0x740, 0x760, 0x798, 0x7c8, 0x7a8, 0x798, 0x7b8, 0x798, 0x7e0, 0xfd0, 0x808, 0x828];
