    /// Edges the corpus run exercised (measured by `hsregion cov`). Any other edge deopts: untested paths never go live.
    pub static EDGE_OK: [bool; NE] = [true, true, false, true, true, true, true, true, true, true, true, true, true, true];
    /// Leave the current block along edge `e`: returns the next block index (stay in the region) or returns from `region`
    /// (exit: pc/npc/now set) or deopts when the edge was never exercised. `c.icount` must already include the block (and
    /// the `-= 1` of a not-taken branch-likely). Needs a `flush!()` macro in scope (writes locals back; empty in plain style).
    macro_rules! go {
        ($c:expr, $fr:expr, $e:expr) => {{
            let e: usize = $e;
            if !super::gen::EDGE_OK[e] {
                flush!();
                return crate::hs::deopt($c, $fr, $fr.pc(super::gen::EDGE_TO[e]), $c.icount);
            }
            let nb = super::gen::EDGE_BLK[e];
            if nb == super::gen::EXIT {
                flush!();
                $c.pc = $fr.pc(super::gen::EDGE_TO[e]);
                $c.npc = $c.pc.wrapping_add(4);
                $c.mem.now = $c.icount;
                return true;
            }
            nb
        }};
    }
    
