    // Q (vi[22]) is a local written by vdiv/vrsqrt and read by vmaddq; flush writes it back.
    use super::gen::*;
    use crate::cpu::Cpu;
    use crate::hs::{deopt, Frame};
    use crate::hs_fast::vu0::{st_of_mac, vdiv, vrsqrt, Chop, Sticky, V};
