        let p13 = V::ld(c.vf[13]).prep();
        let p16 = V::ld(c.vf[16]).prep();
        let p17 = V::ld(c.vf[17]).prep();
        let p18 = V::ld(c.vf[18]).prep();
        let p19 = V::ld(c.vf[19]).prep();
