        let mut v4 = V::ld(c.vf[4]);
        let mut v5 = V::ld(c.vf[5]);
        let mut v6 = V::ld(c.vf[6]);
        let mut v7 = V::ld(c.vf[7]);
        let mut v8 = V::ld(c.vf[8]);
