                    c.s(20, sx32(fm.r32(s5a.wrapping_add(0x94)).unwrap_or(0)));
                    let cond = (lo(c, 22) as i64) >= 0;
                    // delay slot: addi $at, $zero, -0x20
                    c.s(1, (-0x20i64) as u64);
                    if cond {
                        b = go!(c, fr, 12);
                        continue;
                    }
                    b = go!(c, fr, 13);
                    continue;
